#!/usr/bin/env python3
"""Generate the pre-created LoadOnDemand ring slots.

The client only discovers addon folders at startup, so the ring must exist on
disk before WoW starts. The companion will generate the same folders when it
installs the addon; this script is for local development and testing.
"""

from __future__ import annotations

import argparse
import shutil
import sys
from pathlib import Path

DEFAULT_WOW = Path("/games/World of Warcraft")
SLOT_PREFIX = "BaboForever_Data_"

TOC = """## Interface: 16001
## Title: Babo Forever - Live Data {index:02d}
## Notes: Generated by the Babo Forever Companion. Do not edit.
## Author: babo
## Version: 0.1.0
## LoadOnDemand: 1
## X-Category: Auction/Economy

Data.lua
"""

DATA = """-- Generated live ring slot. The companion rewrites this file.
BABOFOREVER_RING = {
  schema = 1,
  market = "",
  window = 0,
  generated = 0,
  base = 0,
  seq = 0,
  items = {},
  removed = {},
  pins = {},
}
"""


def addons_dir(wow: Path) -> Path:
    return wow / "_forever_" / "Interface" / "AddOns"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--wow", default=str(DEFAULT_WOW), help="WoW install root")
    parser.add_argument("--out", help="output directory (default: <wow>/.../AddOns)")
    parser.add_argument("--count", type=int, default=64, help="number of slots")
    parser.add_argument("--force", action="store_true", help="overwrite existing slots")
    parser.add_argument("--remove", action="store_true", help="remove generated slots")
    args = parser.parse_args(argv)

    if args.count < 1 or args.count > 256:
        print("count must be between 1 and 256", file=sys.stderr)
        return 2

    wow = Path(args.wow).expanduser()
    out = Path(args.out).expanduser() if args.out else addons_dir(wow)

    if args.remove:
        removed = 0
        if out.is_dir():
            for path in sorted(out.glob(SLOT_PREFIX + "*")):
                if path.is_dir():
                    shutil.rmtree(path)
                    removed += 1
        print(f"removed {removed} ring slots from {out}")
        return 0

    if not out.exists():
        if args.out:
            out.mkdir(parents=True, exist_ok=True)
        else:
            print(f"AddOns directory not found: {out}", file=sys.stderr)
            return 1

    for index in range(args.count):
        path = out / (SLOT_PREFIX + f"{index:02d}")
        if path.exists():
            if not args.force:
                print(f"exists: {path} (use --force)", file=sys.stderr)
                return 1
            shutil.rmtree(path)
        path.mkdir(parents=True)
        (path / (SLOT_PREFIX + f"{index:02d}" + ".toc")).write_text(
            TOC.format(index=index), encoding="utf-8"
        )
        (path / "Data.lua").write_text(DATA, encoding="utf-8")

    print(f"generated {args.count} ring slots in {out}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
